import { OPERATION_SCHEMA, OPERATION_TABLE, toolInputDefName } from './operation-schema';
import { LARA_TOOLS } from './tools';

/** Directory of the generated files, relative to the workspace root. */
export const SCHEMA_DIR = 'libs/lara-dsl/schema';
export const SCHEMA_FILE = 'lara-dsl.schema.json';
export const TOOLS_FILE = 'lara-tools.json';

/**
 * Contents of the generated schema files (written by `nx run lara-dsl:schema`, checked by a
 * unit test). The .NET backend validates tool arguments against `lara-dsl.schema.json` and
 * sends the tools from `lara-tools.json` to the model (without `strict`: the combined grammar
 * of all tools exceeds Anthropic's limit for strict tools).
 */
export function schemaFiles(): Readonly<Record<string, unknown>> {
  return {
    [SCHEMA_FILE]: OPERATION_SCHEMA,
    [TOOLS_FILE]: {
      $comment:
        'Generated by `nx run lara-dsl:schema` from libs/lara-dsl/src/lib/schema; do not edit. Send `tools` to the model (Anthropic Messages API shape; no strict: the combined grammar exceeds the API limit). Validate the arguments of a call to tool <name> against lara-dsl.schema.json at `operations.<name>.inputSchema`; `operations.<name>.op` is the operation it becomes (insert_module: params list → record).',
      tools: LARA_TOOLS,
      operations: Object.fromEntries(
        OPERATION_TABLE.map((e) => [
          e.tool,
          {
            op: e.op,
            inputSchema: `${SCHEMA_FILE}#/$defs/${toolInputDefName(e.def)}`,
            operationSchema: `${SCHEMA_FILE}#/$defs/${e.def}`,
          },
        ]),
      ),
    },
  };
}
